insert into public.translations (locale, key, value) values
  ('pt-BR', 'orgChat.pick.title', $json$"Escolha um chat geral"$json$::jsonb),
  ('en', 'orgChat.pick.title', $json$"Choose a general chat"$json$::jsonb),
