  ('zh-CN', 'orgChat.pick.title', $json$"选择通用聊天"$json$::jsonb),
  ('hi', 'orgChat.pick.title', $json$"एक सामान्य चैट चुनें"$json$::jsonb),
  ('ar', 'orgChat.pick.title', $json$"اختر محادثة عامة"$json$::jsonb),
  ('fr', 'orgChat.pick.title', $json$"Choisissez un chat général"$json$::jsonb),
