  ('de', 'orgChat.pick.title', $json$"Allgemeinen Chat wählen"$json$::jsonb),
  ('pt-BR', 'orgChat.pick.description', $json$"Os chats gerais de {org} trabalham em todos os repositórios de uma vez. Escolha um para continuar ou comece um novo."$json$::jsonb),
  ('en', 'orgChat.pick.description', $json$"General chats of {org} work on all its repositories at once. Pick one to continue or start a new one."$json$::jsonb),
  ('es', 'orgChat.pick.description', $json$"Los chats generales de {org} trabajan en todos sus repositorios a la vez. Elige uno para continuar o empieza uno nuevo."$json$::jsonb),
  ('zh-CN', 'orgChat.pick.description', $json$"{org} 的通用聊天会同时处理其所有仓库。选择一个继续，或新建一个。"$json$::jsonb),
  ('hi', 'orgChat.pick.description', $json$"{org} की सामान्य चैट उसके सभी रिपॉज़िटरी पर एक साथ काम करती हैं। जारी रखने के लिए एक चुनें या नई शुरू करें।"$json$::jsonb),
  ('ar', 'orgChat.pick.description', $json$"تعمل المحادثات العامة لـ {org} على جميع مستودعاتها دفعة واحدة. اختر واحدة للمتابعة أو ابدأ محادثة جديدة."$json$::jsonb),
  ('fr', 'orgChat.pick.description', $json$"Les chats généraux de {org} travaillent sur tous ses dépôts à la fois. Choisissez-en un pour continuer ou démarrez-en un nouveau."$json$::jsonb),
  ('ru', 'orgChat.pick.description', $json$"Общие чаты {org} работают сразу со всеми её репозиториями. Выберите чат, чтобы продолжить, или начните новый."$json$::jsonb),
  ('ja', 'orgChat.pick.description', $json$"{org} の総合チャットは、そのすべてのリポジトリを一度に扱います。続けるチャットを選ぶか、新しく始めてください。"$json$::jsonb),
  ('de', 'orgChat.pick.description', $json$"Allgemeine Chats von {org} arbeiten an allen Repositories gleichzeitig. Wähle einen zum Fortsetzen oder starte einen neuen."$json$::jsonb),
